// Fake backend for the user-guide screenshots: answers the app's Tauri commands from
// fixtures.json (fictional data generated by src-tauri/src/demo.rs). Never touches Outlook or a database.
import fixtures from "./fixtures.json";

type Any = any; // eslint-disable-line @typescript-eslint/no-explicit-any
const fx: Any = structuredClone(fixtures);
const scenario = new URLSearchParams(location.search).get("scenario") ?? "";

function detail(id: number): Any {
  const d = fx.details[String(id)];
  // fields added with the shared database (older fixtures do not have them)
  d.notes ??= d.ticket.internal_notes ? [{ note_id: `n${id}`, author_name: "Sam Staff", body: d.ticket.internal_notes, created_at: d.ticket.updated_at, updated_at: d.ticket.updated_at, origin: "local", sync_state: "" }] : [];
  d.ownership ??= []; d.completions ??= []; d.conflicts ??= []; d.pending_ops ??= [];
  d.ticket.sync_state ??= "synced"; d.ticket.shared_version ??= 1; d.ticket.shared_state ??= "shared";
  return d;
}

const demoShared = () => ({
  mode: "shared", path: "\\\\fileserver\\Team\\asr_email_support.accdb", state: "connected", reachable: true, readable: true, writable: true,
  database_id: "00000000-demo", database_name: "ASR Support Desk (demo)", environment: "test", schema_version: 1, compatibility: "ok", app_schema_version: 1,
  bound_database_id: "00000000-demo", bound_database_name: "ASR Support Desk (demo)", driver: "Available64", last_success_at: "2026-11-17T15:02:00Z",
  last_attempt_at: "2026-11-17T15:02:00Z", next_attempt_at: "2026-11-17T15:04:00Z", running: false, consecutive_failures: 0,
  queue: { pending: 0, held: 0, conflicts: 0, rejected: 0, isolated: 0 },
});

function err(code: string, message: string): never {
  throw { code, message };
}

function list(q: Any) {
  let rows: Any[] = fx.tickets.map((t: Any) => {
    const d = detail(t.id).ticket;
    return { ...t, status: d.status, completed_at: d.completed_at, assignee_staff_id: d.assignee_staff_id, assignee_name: d.assignee_name, scope_state: d.scope_state, scope_reason: d.scope_reason, sync_state: t.sync_state ?? "synced" };
  });
  if (q.view && q.view !== "all") rows = rows.filter((t) => t.scope_state === q.view);
  if (q.status === "open") rows = rows.filter((t) => t.status !== "Done");
  else if (q.status) rows = rows.filter((t) => t.status === q.status);
  if (q.assignee === "none") rows = rows.filter((t) => t.assignee_staff_id == null);
  else if (q.assignee) rows = rows.filter((t) => String(t.assignee_staff_id) === q.assignee);
  if (q.reason) rows = rows.filter((t) => t.scope_reason === q.reason);
  if (q.issue_type) rows = rows.filter((t) => detail(t.id).issues.some((i: Any) => i.issue_type === q.issue_type) || t.issue_type === q.issue_type);
  if (q.search) {
    const words = String(q.search).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
    rows = rows.filter((t) => {
      const d = detail(t.id);
      const hay = [t.display_id, t.school_name, t.school_njiis_id, t.sender_name, t.sender_email, t.original_subject, d.ticket.internal_notes, d.ticket.staff_actions,
        ...d.fields.map((f: Any) => f.effective), ...d.messages.map((m: Any) => m.body_text)].join(" ").toLowerCase();
      return words.every((w) => hay.includes(w));
    });
  }
  // same date semantics as the backend: from inclusive, to exclusive (the UI sends the day after the end date)
  const inRange = (v: string | null | undefined, from?: string, to?: string) =>
    (!from || (!!v && new Date(v) >= new Date(from))) && (!to || (!!v && new Date(v) < new Date(to)));
  rows = rows.filter((t) => inRange(t.first_received_at, q.received_from, q.received_to) && inRange(t.completed_at, q.completed_from, q.completed_to));
  const key = q.sort === "updated" ? "updated_at" : q.sort === "completed" ? "completed_at" : "first_received_at";
  rows.sort((a, b) => String(b[key] ?? "").localeCompare(String(a[key] ?? "")));
  const offset = q.offset ?? 0;
  return { rows: rows.slice(offset, offset + (q.limit || 100)), total: rows.length, counts: [] };
}

export function handler(cmd: string, args: Any): unknown {
  switch (cmd) {
    case "catalog_get": return fx.catalog;
    case "sync_status": return { running: false, last_success_at: "2026-11-17T15:02:00Z", last_run_at: "2026-11-17T15:02:00Z", next_run_at: "2026-11-17T15:07:00Z", folder_display: fx.scan_summary, warnings: [] };
    case "sync_now": return { report: { seen: 9, new_messages: 2, already_imported: 7, moved: 0, created_tickets: 1, updated_tickets: 1, skipped_internal: 0, duplicates_flagged: 0 }, warnings: [], folders: 2 };
    case "tickets_list": return list(args.query ?? {});
    case "ticket_detail": return detail(args.id);
    case "prompt_get": return fx.prompts[String(args.id)];
    case "prompt_copied": { const d = detail(args.id); d.ticket.last_prompt_at = new Date().toISOString(); return d.ticket.last_prompt_at; }
    case "prompt_default_instructions": return fx.default_prompt;
    case "ticket_update": case "ticket_set_field": case "ticket_set_issues": case "ticket_add_school": case "ticket_remove_school":
      return null;
    case "ticket_reopen": { const d = detail(args.id); d.ticket.status = "In Progress"; d.ticket.completed_at = null; return d.ticket; }
    case "ticket_complete": {
      const d = detail(args.id);
      const incoming = d.messages.filter((m: Any) => !m.is_internal);
      if (scenario === "markdone-error") {
        d.completion = incoming.map((m: Any, i: number) => ({ message_id: m.id, flagged_at: "2026-11-17T15:10:00Z", moved_at: null, dest_path: null,
          last_error: i === 0 ? "Could not move the email to the completion folder (access denied). Check that you can write to that folder. (flagged complete but not moved)" : null, last_error_at: "2026-11-17T15:10:00Z", attempts: 1 }));
        return { done: false, flagged: incoming.length, moved: 0, dest_path: "Inbox/Completed",
          failed: [{ message_id: incoming[0].id, subject: incoming[0].subject, error: d.completion[0].last_error }] };
      }
      if (scenario === "not-configured") err("NOT_CONFIGURED", "Choose a completion folder in Settings › Completion Folder before marking tickets Done. The app never guesses where to archive emails.");
      d.ticket.status = "Done";
      d.ticket.completed_at = new Date().toISOString();
      d.completion = incoming.map((m: Any) => ({ message_id: m.id, flagged_at: d.ticket.completed_at, moved_at: d.ticket.completed_at, dest_path: "Inbox/Completed", last_error: null, attempts: 1 }));
      return { done: true, flagged: incoming.length, moved: incoming.length, failed: [], dest_path: "Inbox/Completed" };
    }
    case "outlook_open_reply":
      if (scenario === "not-found") err("ITEM_NOT_FOUND", "The original email could not be found in Outlook (moved, deleted or no access).");
      return { opened: true, reply_all: !!args.replyAll, message_id: 0, relocated: false };
    case "outlook_open_new": return null;
    case "outlook_test": return { outlook_version: "16.0", profile: "Outlook", default_store: "sam.staff@helpdesk.example.gov", store_count: 2 };
    case "outlook_list_mailboxes": return { mailboxes: fx.mailboxes };
    case "outlook_list_folders":
      return args.rootEntryId ? { store_id: "DEMO-STORE", root: fx.inbox_tree } : { store_id: "DEMO-STORE", root: fx.mailbox_tree };
    case "outlook_validate_folder": return { entry_id: args.entryId, store_id: args.storeId, path: "Inbox/Completed", name: "Completed", mailbox: fx.settings.mailbox_name };
    case "settings_get": return structuredClone(fx.settings);
    case "settings_save": fx.settings = args.settings; return args.settings;
    case "app_info": return { version: "1.0.0", data_dir: "%APPDATA%\\gov.nj.doh.asrsupportdesk", db_path: "%APPDATA%\\gov.nj.doh.asrsupportdesk\\support_desk.db", log_dir: "%APPDATA%\\gov.nj.doh.asrsupportdesk\\logs", startup_ms: 750, schema_version: 2, catalog_version: fx.catalog.catalog_version, template_count: fx.templates.length };
    case "templates_list": return args.issueType ? fx.templates.filter((t: Any) => t.issue_type === args.issueType) : fx.templates;
    case "template_get": return fx.templates.find((t: Any) => t.id === args.id);
    case "template_versions": return [];
    case "template_preview": return { subject: args.subject, body_html: args.bodyHtml, check: { unresolved: [], unverified_claims: [] } };
    case "report_get": return fx.report;
    case "export_csv": return fx.tickets.length;
    case "scope_status": {
      const n = (v: string) => fx.tickets.filter((t: Any) => detail(t.id).ticket.scope_state === v).length;
      return { configured: true, mailbox: fx.settings.mailbox_name, summary: fx.scan_summary, last_ok_at: "2026-11-17T15:02:00Z", last_attempt_at: "2026-11-17T15:02:00Z",
        last_error: null, stale: false, running: false, current: n("current"), history: n("history"), unverified: n("unverified") };
    }
    case "staff_list": return args.includeInactive ? fx.staff : fx.staff.filter((s: Any) => s.active);
    case "staff_current_get": return fx.current_staff_id;
    case "staff_current_set": fx.current_staff_id = args.id; return null;
    case "staff_save": return { ...args.input, id: args.input.id ?? 99, active: true, created_at: "", updated_at: "" };
    case "staff_set_active": return { ...fx.staff.find((s: Any) => s.id === args.id), active: args.active };
    case "outlook_list_accounts": return { accounts: fx.accounts };
    case "assign_preview": {
      const to = fx.staff.find((s: Any) => s.id === args.staffId);
      return args.ticketIds.map((id: number) => {
        const d = detail(id);
        const emails = d.messages.filter((m: Any) => !m.is_internal && m.entry_id).length;
        return { ticket_id: id, display_id: d.ticket.display_id, from_name: d.ticket.assignee_name, to, emails, already_in_folder: 0,
          will_notify: d.ticket.assignee_staff_id !== args.staffId, blocked: d.ticket.status === "Done" ? "This ticket is Done. Reopen it before assigning it." : null };
      });
    }
    case "tickets_assign": {
      const to = fx.staff.find((s: Any) => s.id === args.staffId);
      return args.ticketIds.map((id: number) => {
        const d = detail(id);
        d.ticket.assignee_staff_id = to.id; d.ticket.assignee_name = to.display_name; d.ticket.status = "Assigned";
        return { ticket_id: id, display_id: d.ticket.display_id, result: "assigned", message: `Assigned to ${to.display_name}. Notification submitted to Outlook (delivery not confirmed).`,
          failures: [], op_id: 1, notify_state: "submitted", notify_error: null };
      });
    }
    case "notification_retry": {
      for (const d of Object.values(fx.details) as Any[]) for (const o of d.assignments) if (o.id === args.opId) { o.notify_state = "submitted"; o.notify_error = null; o.notify_at = new Date().toISOString(); }
      return ["submitted", null];
    }
    case "notification_check": return "Not found in Sent Items or Outbox. If you are sure it was not sent, choose Send again.";
    case "notification_resend": return ["submitted", null];
    case "assignment_retry": return { ticket_id: args.ticketId, display_id: "", result: "assigned", message: "Assigned.", failures: [], notify_state: "submitted" };
    case "ticket_start_work": { const d = detail(args.id); d.ticket.status = "In Progress"; return d.ticket; }
    case "overview_get": return { ...fx.overview, last_reconciled_at: "2026-11-17T15:02:00Z" };
    case "shared_status": case "shared_test_connection": case "shared_sync_now": return demoShared();
    case "shared_import_preview": return { local_only: 0, with_message_id: 0, without_message_id: 0, done: 0, open: 0, staff: fx.staff.length, already_shared: 0, held_ops: 0 };
    case "notes_add": { const d = detail(args.ticketId); const n = { note_id: `n${Date.now()}`, author_name: "Sam Staff", body: args.body, created_at: new Date().toISOString(), updated_at: new Date().toISOString(), origin: "local", sync_state: "" }; d.notes.push(n); return n; }
    case "conflicts_list": return [];
    case "diag_recent": return [
      { id: 3, at: "2026-11-17T15:02:00Z", severity: "info", component: "sync", code: "SYNC_OK", summary: "Synchronized: sent 2 change(s) (2 accepted, 0 conflict, 0 rejected, 0 replayed), received 1 case(s)", detail: "elapsed 180 ms", correlation: null },
      { id: 2, at: "2026-11-17T14:40:00Z", severity: "warning", component: "shared-db", code: "SHARE_UNAVAILABLE", summary: "Shared database unavailable: The shared folder cannot be reached. Your changes are saved on this computer.", detail: "", correlation: null },
      { id: 1, at: "2026-11-17T14:30:00Z", severity: "info", component: "startup", code: "APP_START", summary: "ASR/Audit Support Desk 1.1.0 started; local schema v4; shared mode shared", detail: "", correlation: null },
    ];
    case "diag_overview": return { header: { app_version: "1.1.0", local_schema: 4, shared_mode: "shared", shared_state: "connected", shared_database: "ASR Support Desk (demo)", shared_environment: "test", shared_schema: 1, last_success_at: "2026-11-17T15:02:00Z", pending: 0, held: 0, conflicts: 0, failed: 0, driver: "Available64", device: "1a2b3c4d" }, latest_error_id: null, log_dir: "%APPDATA%\\gov.nj.doh.asrsupportdesk\\logs" };
    case "diag_copy_text": return "ASR/Audit Support Desk - Diagnostics (demo)";
    case "diag_report": return null;
    case "plugin:event|listen": return 1;
    case "plugin:event|unlisten": return null;
    default:
      console.warn("demo mock: unhandled command", cmd, args);
      return null;
  }
}
